/*
 * A062516  Numbers k such that 2*tau(k) = phi(k).
 * https://oeis.org/A062516
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   Numbers k such that 2*tau(k) = phi(k). Generated by exhaustive *
 *            search over all possible prime power combinations of the small
 *            primes * {2,3,5,7} that can satisfy the equation. The list of
 *            solutions is * found by checking that the product of the terms *
 *            R(p,e) = p^(e-1)*(p-1)/(e+1) * equals 2. T...
 * Range:     u8 n <= 9, u16 n <= 9, u32 n <= 9, u64 n <= 9, u128 n <= 9,
 *            big any n
 * Helpers:   u64_gcd
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include "../utils/u64_gcd.h"

/* comparison function for qsort */
static int cmp_seq_t(const void *p1, const void *p2)
{
    const seq_t *a = (const seq_t *)p1;
    const seq_t *b = (const seq_t *)p2;
    if (*a < *b) return -1;
    if (*a > *b) return 1;
    return 0;
}

seq_t a(idx_t n)
{
    /* static storage for solutions */
    static seq_t sol[256];
    static size_t solCnt = 0;
    static int initialized = 0;

    if (!initialized) {
        size_t idx = 0;
        /* exhaustive search over combinations of prime powers 2^e2 * 3^e3 * 5^e5 * 7^e7 */
        for (int e2 = 0; e2 <= 5; ++e2) {
            for (int e3 = 0; e3 <= 4; ++e3) {
                for (int e5 = 0; e5 <= 1; ++e5) {
                    for (int e7 = 0; e7 <= 1; ++e7) {
                        if (e2 == 0 && e3 == 0 && e5 == 0 && e7 == 0)
                            continue; /* skip 1 */
                        seq_t num = 1;
                        seq_t r_num = 1;
                        seq_t r_den = 1;
                        /* prime 2 */
                        if (e2 > 0) {
                            seq_t p2pow = 1;
                            for (int i = 0; i < e2; ++i) p2pow *= 2;
                            num *= p2pow;
                            seq_t Rnum = (seq_t)1 << (e2 - 1);  /* 2^(e2-1) */
                            seq_t Rden = e2 + 1;
                            r_num *= Rnum;
                            r_den *= Rden;
                        }
                        /* prime 3 */
                        if (e3 > 0) {
                            seq_t p3pow = 1;
                            for (int i = 0; i < e3; ++i) p3pow *= 3;
                            num *= p3pow;
                            seq_t Rnum = 1;
                            for (int i = 0; i < e3 - 1; ++i) Rnum *= 3;
                            Rnum *= 2;  /* (3-1) */
                            seq_t Rden = e3 + 1;
                            r_num *= Rnum;
                            r_den *= Rden;
                        }
                        /* prime 5 */
                        if (e5 > 0) {
                            seq_t p5pow = 1;
                            for (int i = 0; i < e5; ++i) p5pow *= 5;
                            num *= p5pow;
                            seq_t Rnum = 1;
                            for (int i = 0; i < e5 - 1; ++i) Rnum *= 5;
                            Rnum *= 4;  /* (5-1) */
                            seq_t Rden = e5 + 1;
                            r_num *= Rnum;
                            r_den *= Rden;
                        }
                        /* prime 7 */
                        if (e7 > 0) {
                            seq_t p7pow = 1;
                            for (int i = 0; i < e7; ++i) p7pow *= 7;
                            num *= p7pow;
                            seq_t Rnum = 1;
                            for (int i = 0; i < e7 - 1; ++i) Rnum *= 7;
                            Rnum *= 6;  /* (7-1) */
                            seq_t Rden = e7 + 1;
                            r_num *= Rnum;
                            r_den *= Rden;
                        }
                        /* reduce fraction r_num/r_den */
                        uint64_t g = u64_gcd((uint64_t)r_num, (uint64_t)r_den);
                        r_num /= g;
                        r_den /= g;
                        if (r_num == (seq_t)2 && r_den == (seq_t)1) {
                            sol[idx++] = num;
                        }
                    }
                }
            }
        }
        solCnt = idx;
        /* sort the solutions */
        qsort(sol, solCnt, sizeof(seq_t), cmp_seq_t);
        initialized = 1;
    }

    if (n == 0) return (seq_t)0;             /* offset starts at 1 */
    if (n - 1 < solCnt) return sol[n - 1];
    return (seq_t)0;                         /* beyond known terms */
}
